-- 075 — BPF: fichas completadas conforme os POPs (rev. 00, antes da primeira emissão do PDF)
create or replace function pg_temp.c(p_cod text,p_id text) returns jsonb language sql as $$ select c from bpf_formularios f, jsonb_array_elements(f.campos) c where f.codigo=p_cod and c->>'id'=p_id $$;
update bpf_formularios set campos=(select jsonb_agg(x order by n) from unnest(array[pg_temp.c('REG-POP01-01','hora'),pg_temp.c('REG-POP01-01','embalagem'),pg_temp.c('REG-POP01-01','codigo_item'),pg_temp.c('REG-POP01-01','fornecedor'),pg_temp.c('REG-POP01-01','fornecedor_homologado'),pg_temp.c('REG-POP01-01','lote'),pg_temp.c('REG-POP01-01','nota_fiscal'),pg_temp.c('REG-POP01-01','quantidade'),'{"id": "sec_insp", "tipo": "secao", "label": "Inspeção da embalagem (POP-01, 6.d)"}'::jsonb,'{"id": "tipo_ok", "tipo": "sim_nao", "label": "Tipo conforme a especificação (sacaria valvulada com fundo colado / Big Bag especificado)?", "conforme": "sim", "obrigatorio": true}'::jsonb,'{"id": "capacidade_ok", "tipo": "sim_nao", "label": "Capacidade conforme (25 kg / Big Bag do produto)?", "conforme": "sim", "obrigatorio": true}'::jsonb,'{"id": "sujidade", "tipo": "sim_nao", "label": "Sem sujidade, rasgo, furo ou costura aberta?", "conforme": "sim", "obrigatorio": true}'::jsonb,pg_temp.c('REG-POP01-01','integridade') || '{"label": "Embalagem seca, sem umidade?"}'::jsonb,'{"id": "decisao", "tipo": "select", "label": "Decisão do recebimento", "opcoes": ["Aceito", "Devolvido ao fornecedor"], "obrigatorio": true, "ajuda": "Avaria: não aceitar e devolver ao fornecedor (POP-01, item 10)"}'::jsonb,'{"id": "sec_est", "tipo": "secao", "label": "Estocagem (POP-01, 6.e)"}'::jsonb,pg_temp.c('REG-POP01-01','estoque_anterior'),pg_temp.c('REG-POP01-01','peps'),'{"id": "deposito_ok", "tipo": "sim_nao", "label": "Depósito fechado, organizado e livre de objetos em desuso?", "conforme": "sim", "obrigatorio": true}'::jsonb,pg_temp.c('REG-POP01-01','obs')]) with ordinality u(x,n) where x is not null) where codigo='REG-POP01-01';
update bpf_formularios set campos=(select jsonb_agg(x order by n) from unnest(array[pg_temp.c('REG-POP01-02','nome'),pg_temp.c('REG-POP01-02','cnpj'),pg_temp.c('REG-POP01-02','categoria'),pg_temp.c('REG-POP01-02','tipo_forn'),pg_temp.c('REG-POP01-02','docs_ok'),'{"id": "especificacao_ok", "tipo": "sim_nao", "label": "Especificação técnica ou laudo do material/serviço apresentado?", "conforme": "sim", "obrigatorio": true, "ajuda": "Categorias A e B (POP-01, 6.b)"}'::jsonb,pg_temp.c('REG-POP01-02','status'),'{"id": "homologado_em", "tipo": "data", "label": "Data da homologação"}'::jsonb,pg_temp.c('REG-POP01-02','reavaliacao'),pg_temp.c('REG-POP01-02','obs')]) with ordinality u(x,n) where x is not null) where codigo='REG-POP01-02';
update bpf_formularios set campos=(select jsonb_agg(x order by n) from unnest(array['{"id": "motivo", "tipo": "select", "label": "Motivo da limpeza", "opcoes": ["Fim do expediente", "Fim de lote", "Troca de variação", "Outro"], "obrigatorio": true}'::jsonb,pg_temp.c('REG-POP03-01','hora_ini'),pg_temp.c('REG-POP03-01','hora_fim'),pg_temp.c('REG-POP03-01','areas'),'{"id": "executante", "tipo": "funcionario", "label": "Executante", "obrigatorio": true}'::jsonb,pg_temp.c('REG-POP03-01','destino_varredura'),'{"id": "sec_crit", "tipo": "secao", "label": "Critério de linha limpa (POP-03, 6.c)"}'::jsonb,'{"id": "l1", "tipo": "sim_nao", "label": "Sem acúmulo de pó sobre tubulações, estruturas, ensacadeira e piso?", "conforme": "sim", "obrigatorio": true}'::jsonb,'{"id": "l2", "tipo": "sim_nao", "label": "Sem resíduo do material anterior nos pontos de acesso da linha?", "conforme": "sim", "obrigatorio": true}'::jsonb,'{"id": "l3", "tipo": "sim_nao", "label": "Sem objeto, ferramenta ou embalagem estranha ao processo na área?", "conforme": "sim", "obrigatorio": true}'::jsonb,'{"id": "l4", "tipo": "sim_nao", "label": "Utensílios recolhidos aos suportes?", "conforme": "sim", "obrigatorio": true}'::jsonb,'{"id": "liberado", "tipo": "sim_nao", "label": "Área liberada para a moagem (conferência do encarregado)?", "conforme": "sim", "obrigatorio": true, "ajuda": "O início da moagem depende desta conferência e da inspeção de equipamentos vazios (POP-06)"}'::jsonb,pg_temp.c('REG-POP03-01','obs')]) with ordinality u(x,n) where x is not null) where codigo='REG-POP03-01';
update bpf_formularios set campos=(select jsonb_agg(x order by n) from unnest(array[pg_temp.c('REG-POP05-01','hora_ini'),pg_temp.c('REG-POP05-01','hora_fim'),pg_temp.c('REG-POP05-01','local'),pg_temp.c('REG-POP05-01','executor'),pg_temp.c('REG-POP05-01','empresa'),pg_temp.c('REG-POP05-01','capacitacao_vigente'),'{"id": "sec_exec", "tipo": "secao", "label": "Execução (POP-05, 6.c)"}'::jsonb,'{"id": "entrada_fechada", "tipo": "sim_nao", "label": "Entrada de água fechada / boia amarrada antes da limpeza?", "conforme": "sim", "obrigatorio": true}'::jsonb,'{"id": "sem_quimicos", "tipo": "sim_nao", "label": "Lavado com pano/escova de fibra, sem escova de aço, sabão, detergente ou químicos?", "conforme": "sim", "obrigatorio": true}'::jsonb,'{"id": "desinfeccao", "tipo": "sim_nao", "label": "Desinfecção com hipoclorito de sódio na concentração e no tempo de contato da IT?", "conforme": "sim", "obrigatorio": true}'::jsonb,pg_temp.c('REG-POP05-01','obs')]) with ordinality u(x,n) where x is not null) where codigo='REG-POP05-01';
update bpf_formularios set campos=(select jsonb_agg(x order by n) from unnest(array[pg_temp.c('REG-POP12-01','total_vigentes'),'{"id": "aprovacao_completa", "tipo": "sim_nao", "label": "Documentos com código, revisão, datas coerentes e aprovação completa?", "conforme": "sim", "obrigatorio": true, "ajuda": "POP-12, item 8"}'::jsonb,'{"id": "pontos_uso_ok", "tipo": "sim_nao", "label": "Pontos de uso com a versão vigente?", "conforme": "sim", "obrigatorio": true}'::jsonb,pg_temp.c('REG-POP12-01','obsoletos_recolhidos'),pg_temp.c('REG-POP12-01','divergencias')]) with ordinality u(x,n) where x is not null) where codigo='REG-POP12-01';
update bpf_formularios set campos=(select jsonb_agg(case when c->>'id'='nota_prova' then c||'{"min": 70, "unidade": "%", "ajuda": "Nota mínima de 70% (POP-20, 6.c)"}'::jsonb else c end order by o) from jsonb_array_elements(campos) with ordinality e(c,o)) where codigo='REG-POP20-02';
update bpf_formulario_versoes v set campos=f.campos, alteracoes='Rev. 00 — campos completados conforme o POP' from bpf_formularios f where f.codigo=v.formulario_cod and v.status='vigente' and v.formulario_cod in ('REG-POP01-01','REG-POP01-02','REG-POP03-01','REG-POP05-01','REG-POP12-01','REG-POP20-02');